local heal={
 SHAMAN=recipe('Target the endangered ally and check whether a cast can finish before the next hit.',{basic('Nature\'s Swiftness','An immediate qualifying Nature heal is required and the cooldown is ready.','Prepare the instant response.','Nature\'s Swiftness'),basic('Healing Wave','Nature\'s Swiftness is active and the endangered ally is in range.','Spend the instant cast on the lifesaving target.'),basic('Lesser Healing Wave','The ally cannot wait for Healing Wave, but can survive the shorter cast.','Land the faster direct heal.'),basic('Healing Wave','No faster emergency response is needed and the ally can survive its cast.','Use the longer direct recovery when it has time to land.')},'Do not stop an assigned lethal enemy cast just to perform optional off-healing.'),
 DRUID=recipe('If you are tanking, arrange relief before leaving Bear Form to hard-cast a heal.',{basic('Nature\'s Swiftness','An immediate qualifying Nature heal is needed and you can safely perform the healing assignment.','Prepare the instant cast.','Nature\'s Swiftness'),basic('Healing Touch','The instant-heal effect is active, or the ally can survive the normal cast and you can safely cast it.','Land direct recovery on the endangered ally.'),basic('Rejuvenation','The ally needs continued recovery and can survive until useful ticks land.','Use periodic healing after urgent recovery is handled.')},'Do not use Rejuvenation alone when the ally will die before its healing can save them.'),
 PRIEST=recipe('Target the ally at risk and check shielding restrictions.',{basic('Power Word: Shield','The ally needs immediate protection and can receive your shield.','Protect before the next hit.'),basic('Flash Heal','The ally needs direct recovery and can survive until the short cast completes.','Land direct healing instead of another periodic refresh.'),basic('Renew','The immediate danger is controlled and the ally needs continued recovery.','Use periodic healing for sustained missing Health.')},'Do not replace an urgent direct response with Renew if the ally cannot survive until its ticks.'),
 PALADIN=recipe('Target the endangered ally. Check whether Flash of Light is sufficient and whether Holy Light has time to land.',{basic('Lay on Hands','An emergency heal is required, the cooldown is available, and the current effect\'s restrictions permit using it.','Use the emergency tool when ordinary casts cannot safely solve the danger.'),basic('Flash of Light','It will arrive in time and restore enough Health to survive the next hit.','Use the short direct heal when it solves the deficit.'),basic('Holy Light','More recovery is needed and the target can survive its cast.','Land the larger heal when its cast window exists.')},'Do not choose the smaller heal if it leaves the ally dead to the next hit.')
}
local selfRecovery=recipe('Create a safe recovery window before trying to heal yourself.',{step(nil,'You have a usable Healthstone or healing potion, need immediate Health, and its cooldown permits it.','Use the Healthstone or healing potion from your inventory.','Use an actual available recovery item; this does not assume the item is present.'),step(nil,'You have a bandage, can safely channel without incoming damage, and current bandage restrictions permit it.','Use the bandage during that safe window.','Damage can interrupt the channel; it is not an answer while an enemy is still hitting you.')},'Do not channel a bandage under continuous damage or assume your damage spec has a healing spell.')
