 MAGE={basic('Polymorph','The assigned off-target is not already controlled, is eligible, is not taking periodic damage, and your team will not break the control.','Remove that opponent from the exchange before committing damage.'),basic('Counterspell','The assigned enemy healer or caster begins a dangerous interruptible cast.','Stop the cast instead of spending another damage global.')},
 DRUID={basic('Cyclone','The assigned control target can be affected and the current effect will not block your team\'s planned kill or healing.','Coordinate the control window; the target\'s interaction rules matter.','Cyclone'),basic('Entangling Roots','A melee opponent is pursuing your teammate and can be rooted.','Peel that opponent before resuming your own throughput.')},
 PRIEST={basic('Dispel Magic','The agreed friendly or hostile Magic effect can be removed and removal helps the current exchange.','Remove the specific effect rather than dispelling blindly.'),basic('Psychic Scream','Nearby opponents can be feared and your team has a safe plan for the resulting control.','Use the control to peel or create a coordinated kill window.')},
 PALADIN={basic('Hammer of Justice','The agreed control target can be stunned and the stun will not be wasted by immunity or overlapping control.','Create the coordinated control window.'),basic('Blessing of Freedom','Your teammate is hindered by a movement restriction the effect can address and needs to escape or connect.','Restore the teammate\'s ability to move.')},
 ROGUE={basic('Kick','The assigned enemy healer or caster begins an interruptible cast while in melee reach.','Stop the named cast before spending Energy on damage.'),basic('Kidney Shot','You have combo points, the target can be stunned, and the team has called the control window.','Spend the finisher on control instead of damage when the setup requires it.')},
 WARRIOR={basic('Pummel','The assigned healer or caster begins an interruptible cast and your current requirements are met.','Prevent the cast before continuing damage.'),basic('Hamstring','The enemy can be slowed and must be kept away from an ally or within melee reach.','Control distance instead of blindly chasing.')},
 HUNTER={basic('Freezing Trap','The assigned opponent is eligible and your team and pet will not break the control.','Create off-target control before focusing the kill target.'),basic('Concussive Shot','The enemy can be slowed and must be peeled or kept within your team\'s control.','Manage distance while preserving safe ranged positioning.')},
 WARLOCK={basic('Fear','The assigned opponent can be feared and the resulting movement will not ruin your team\'s setup.','Create coordinated off-target control.'),basic('Death Coil','An eligible opponent must be stopped briefly so you or an ally can survive or complete the setup.','Use the actual short control/recovery window instead of another hard cast.')}
}
local function copySteps(steps)local result={} for _,s in ipairs(steps or {}) do result[#result+1]=s end return result end
function A:Situations(class,index,role,base)
 local result={};for key,value in pairs(base) do result[key]=value end
 result.aoe=recipe((role=='healer' and 'Several allies are under group damage. ' or 'Three or more enemies may be damaged together. ')..base.group.prepare,base.group.steps,base.group.avoid)
 local interruptSteps=interrupts[class] or {}
 result.interrupt=recipe('Identify the exact cast you are assigned to stop. Reserve the named interrupt and its resource cost.',interruptSteps,'Do not count a slow, dispel or stun as a guaranteed interrupt against an immune target.')
 result.kite=kite[class]
 result.heal=heal[class] or selfRecovery
 local cleave=copySteps(base.single.steps)
 if role=='healer' then
  result.cleave=recipe('Two enemies are active: keep the tank in range and check whether a second ally is taking damage.',cleave,'Do not switch to damage while the assigned tank needs healing.')
 else
  local extra={
   SHAMAN=basic('Chain Lightning','Exactly two useful enemies can be hit, the jumps will not break control, and its cast is safe or instant from your observed proc.','Add the second useful hit without abandoning the kill target.'),
   MAGE=basic('Living Bomb','The secondary enemy needs a fresh application, will survive useful ticks, and the explosion will not hit controlled targets.','Add sustained damage to the second target without blindly casting an area spell.','Living Bomb'),
   DRUID=index==2 and basic('Rake','Your primary-target combo points have been spent and the secondary enemy will survive useful bleed ticks.','Apply the secondary bleed without wasting accumulated primary-target combo points.') or basic('Moonfire','The secondary enemy will live for useful ticks and does not have your application.','Add a useful periodic effect before returning to the priority target.'),
   ROGUE=index==2 and basic('Blade Flurry','The second enemy is in cleave reach and both targets may be damaged.','Activate the named two-target cleave.','Blade Flurry') or nil,
   WARRIOR=basic('Cleave','Exactly two assigned enemies are in reach and the Rage cost will not prevent the next required interrupt or defensive.','Spend excess Rage on the extra target while preserving required actions.'),
   HUNTER=basic('Multi-Shot','The two intended enemies are in valid coverage and any additional possible hit is safe.','Use the extra shot without breaking a trap or pulling another enemy.'),
   WARLOCK=basic('Corruption','The secondary enemy will survive useful ticks and needs your fresh application.','Maintain a concrete second-target effect, then return to the kill target.'),
   PALADIN=basic('Divine Storm','Both assigned enemies are within its area and no controlled enemy will be hit.','Apply the named melee area attack to the two useful targets.','Divine Storm'),
   PRIEST=basic('Shadow Word: Pain','The secondary enemy will live for useful ticks and needs your periodic effect.','Add sustained damage without repeatedly changing targets for no gain.')
  }
  if extra[class] then table.insert(cleave,1,extra[class]) end
  result.cleave=recipe('Keep one primary kill target. Only add damage to the second enemy when that enemy may be hit.',cleave,'Do not abandon priority-target damage or break control just because two enemies are present.')
 end
 local pvp=copySteps(pvpControl[class]);for _,s in ipairs(base.single.steps) do pvp[#pvp+1]=s end
 result.pvp=recipe('Agree the kill target and off-target control with your team. Check range, line of sight and active control immunity before committing.',pvp,'Do not break your team\'s control, overlap a stop without a reason, or keep hard-casting while a melee opponent can connect.')
 return result
end
